22: export interface PageResult<T> { total: number; rows: T[] }
23: 
24: function queryString(params: Record<string, unknown> = {}): string {
25:   const q = new URLSearchParams()
26:   Object.entries(params).forEach(([k, v]) => {
27:     if (v !== undefined && v !== null && v !== '') q.set(k, String(v))
28:   })
29:   const s = q.toString()
30:   return s ? `?${s}` : ''
31: }
32: 
33: /** 统一解包分页响应：兼容根级 PageResult 与 {code,msg,data} 两种包裹 */
34: async function page<T>(path: string, params: Record<string, unknown> = {}): Promise<PageResult<T>> {
35:   const body = await request<unknown>(`${path}${queryString(params)}`, { raw: true })
36:   const b = (body ?? {}) as {
37:     total?: number | string; rows?: T[]
38:     data?: { total?: number | string; rows?: T[] }
39:     code?: number; msg?: string
40:   }
41:   if (b.code !== undefined && b.code !== 200 && b.code !== 0) throw new Error(b.msg || `接口异常（code ${b.code}）`)
42:   const src = b.data && !Array.isArray(b.rows) ? b.data : b
43:   return { total: Number(src?.total ?? 0) || 0, rows: Array.isArray(src?.rows) ? src.rows : [] }
44: }
45: 
46: /** 详情/单对象接口：走 request 的 {code,msg,data} 解包 */
47: function detail<T>(path: string, params: Record<string, unknown> = {}, headers?: Record<string, string>): Promise<T> {
48:   return request<T>(`${path}${queryString(params)}`, headers ? { headers } : {})
49: }
