import { test, expect, type Page } from '@playwright/test'

/**
 * 验证：「我的」页用户信息取自登录接口返回结果（管理端账号），不再调用 C 端 profile 接口。
 * 登录接口 /api/v2.0/security/auth/login 返回 data（nickName=管理员、userName=zsbase、phone），
 * 登录后缓存并展示；不应再显示设计稿静态数据（陈乔乔 / 300007）。
 */
const PROJECT_ID = 'suzhufang'
const ENCRYPTED_PWD = 'H03W0LoMA6EFQZIW46BnNA=='
const LOGIN_USER = 'zsbase'
const TOKEN_KEY = 'flood-token-v1'
const LOGIN_USER_KEY = 'flood-login-user-v1'

async function doUiLogin(page: Page) {
  await page.goto('/#/pages/login/index', { waitUntil: 'networkidle' }).catch(() => {})
  await page.waitForTimeout(800)
  // 用户登录 tab 下：第一个 text input 用户名，密码 input
  const userInput = page.locator('input[type="text"], input:not([type])').first()
  await expect(userInput).toBeVisible({ timeout: 20_000 })
  await userInput.fill(LOGIN_USER)
  const pwdInput = page.locator('input[type="password"]').first()
  await pwdInput.fill('Zs@2026Aa!')
  // 图形验证码（如开启，需人工；此处尽量填）
  const captcha = page.locator('input[maxlength="4"]').first()
  if (await captcha.count()) await captcha.fill('0000').catch(() => {})
  // 勾选协议
  const agree = page.getByText('请勾选同意用户协议和隐私协议').first()
  if (await agree.count()) await agree.click().catch(() => {})
  await page.getByText('登录', { exact: true }).last().click()
  await page.waitForTimeout(3000)
}

test('我的页展示登录接口返回的用户信息（管理员/zsbase），非 C 端 profile 静态数据', async ({ page }) => {
  // 优先直接用接口拿 token，并模拟登录接口返回的 data 结构缓存到本地（等价于 login() 的落库）
  const res = await page.request.post('/api/v2.0/security/auth/login', {
    headers: { 'Content-Type': 'application/json', 'zhi-project-id': PROJECT_ID },
    data: { username: LOGIN_USER, password: ENCRYPTED_PWD },
  })
  const body = await res.json().catch(() => null) as { code?: number; data?: Record<string, unknown> } | null
  const token = (body?.data?.accessToken ?? body?.data?.token) as string | undefined
  expect(token, '登录接口应返回令牌').toBeTruthy()

  // 用真实登录接口的 data 构造缓存（与 login() 中 merged 逻辑等价：合并 user + 扁平 data，剔除 token）
  const data = body!.data as Record<string, unknown>
  const nested = data.user && typeof data.user === 'object' ? data.user as Record<string, unknown> : {}
  const merged: Record<string, unknown> = { ...nested, ...data }
  delete merged.token; delete merged.accessToken; delete merged.user

  await page.addInitScript(([tk, tkKey, lu, luKey]) => {
    try { window.localStorage.setItem(tkKey as string, tk as string) } catch {}
    try { window.localStorage.setItem(luKey as string, lu as string) } catch {}
  }, [token, TOKEN_KEY, JSON.stringify(merged), LOGIN_USER_KEY] as const)

  await page.goto('/#/pages/mine/index', { waitUntil: 'networkidle' }).catch(() => page.goto('/#/pages/mine/index'))
  await page.waitForTimeout(1500)

  const cardText = await page.locator('.user-card').first().innerText().catch(() => '')
  console.log('===== 我的页用户卡文本 =====\n' + cardText)
  // 应显示登录接口返回的 nickName / userName
  expect(cardText).toContain('管理员')
  expect(cardText).toContain('zsbase')
  // 不应再是 C 端 profile 静态数据
  expect(cardText).not.toContain('陈乔乔')
  expect(cardText).not.toContain('300007')

  await page.screenshot({ path: 'test-results/mine-userinfo.png' })
})
